CREATE TABLE notification(id UUID PRIMARY KEY,request_id UUID NOT NULL,user_id BIGINT NOT NULL,report_id UUID NOT NULL,recipient_email VARCHAR(254) NOT NULL,status VARCHAR(30) NOT NULL,created_at TIMESTAMPTZ NOT NULL,CONSTRAINT uk_notification_request_report UNIQUE(request_id,report_id));
CREATE TABLE outbox_event(outbox_event_id VARCHAR(36) PRIMARY KEY,event_id VARCHAR(36) NOT NULL UNIQUE,event_type VARCHAR(80) NOT NULL,aggregate_id VARCHAR(100) NOT NULL,topic VARCHAR(120) NOT NULL,event_key VARCHAR(100) NOT NULL,payload TEXT NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMPTZ NOT NULL,published_at TIMESTAMPTZ);
CREATE INDEX idx_outbox_status_created ON outbox_event(status,created_at);
CREATE TABLE processed_event(processed_event_id UUID PRIMARY KEY,event_id VARCHAR(36) NOT NULL,consumer_name VARCHAR(100) NOT NULL,processed_at TIMESTAMPTZ NOT NULL,CONSTRAINT uk_processed_event_consumer UNIQUE(event_id,consumer_name));
